#!/usr/bin/env node
// AUTO-GENERATED by gen-world-payload.mjs — do not hand-edit heavy/world/payload.json.
//
// The tiered payload ledger (master-plan.md#M43, world-v2-spec.md §9):
// separate from heavy/world/assets.json (Poly Haven provenance, P2-07c) so
// kit lanes adding a new GLB or texture never have to touch either file —
// this walks the real directory listing instead of a hand-kept table.
//
// Tier is inferred from each file's top-level heavy/world/ subdirectory,
// the one fact a plain listing actually gives us:
//   terrain/, textures/  -> "A"      first-view (before the first frame)
//   models/, and any      -> "B"      idle-loaded after the first frame
//     other future subdir
//   concept/              -> "plates" the static concept-painting fallback
// A handful of named files are ledger/provenance documents a browser never
// fetches at runtime (assets.json, ASSETS.md, concept.json, this script's
// own payload.json) — tagged "meta", listed for completeness but excluded
// from worldPayload.test.ts's byte budgets, the same way the old manual
// table never counted a manifest against itself.
//
// Deterministic (G13): generatedAt is the newest mtime among the files
// listed, never Date.now() — two runs over the same committed tree give
// byte-identical output. Per the house generator contract, a missing
// heavy/world/ exits 0 and leaves any previously committed payload.json
// untouched rather than crashing the chain.
import { existsSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { join, relative, dirname, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const WORLD_DIR = join(root, "heavy", "world");
const OUT_PATH = join(WORLD_DIR, "payload.json");

// payload.json itself is never walked (see the self-reference filter below),
// so it needs no entry here; named for the reader, not for the code path.
const META_FILES = new Set(["assets.json", "ASSETS.md", "concept.json"]);
const TIER_BY_TOP_DIR = { terrain: "A", textures: "A", concept: "plates" };
const DEFAULT_TIER = "B"; // models/, and any future kit subdirectory

function walk(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

function tierFor(relPath, fileName) {
  if (META_FILES.has(fileName)) return "meta";
  const topDir = relPath.split("/")[0];
  return TIER_BY_TOP_DIR[topDir] ?? DEFAULT_TIER;
}

function main() {
  if (!existsSync(WORLD_DIR)) {
    console.log("[gen-world-payload] heavy/world/ missing — leaving any committed payload.json untouched");
    return;
  }

  const rows = walk(WORLD_DIR)
    .filter((abs) => abs !== OUT_PATH) // never read our own prior output as an input (self-reference would break G13 determinism)
    .map((abs) => {
      const relPath = relative(WORLD_DIR, abs).split(sep).join("/");
      const st = statSync(abs);
      const fileName = relPath.split("/").pop();
      return { path: `heavy/world/${relPath}`, bytes: st.size, tier: tierFor(relPath, fileName), mtimeMs: st.mtimeMs };
    })
    .sort((a, b) => a.path.localeCompare(b.path));

  const generatedAtMs = rows.reduce((max, r) => Math.max(max, r.mtimeMs), 0);
  const generatedAt = new Date(generatedAtMs || Date.now()).toISOString();

  const byTier = {};
  for (const row of rows) byTier[row.tier] = (byTier[row.tier] ?? 0) + row.bytes;
  const totalBytes = rows.filter((r) => r.tier !== "meta").reduce((n, r) => n + r.bytes, 0);

  const payload = {
    generatedAt,
    totalBytes,
    byTier,
    files: rows.map(({ path, bytes, tier }) => ({ path, bytes, tier })),
  };

  writeFileSync(OUT_PATH, JSON.stringify(payload, null, 2) + "\n");
  console.log(`[gen-world-payload] wrote ${relative(root, OUT_PATH)}: ${rows.length} files, ${totalBytes.toLocaleString("en-US")} B total`);
}

main();
